// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.ForeignKeyimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — Semantic fact entity (Table 2). * * General facts, independent of when learned. Uses Bayesian confidence * (alpha/beta) for uncertainty quantification. Supports temporal versioning * via [supersededBy]. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "semantic_facts",    indices = [        Index("subject_entity_id"),        Index("predicate"),        Index("superseded_by"),    ],    // ForeignKeys removed — enforced via migration SQL instead    // (KSP has issues resolving cross-file ForeignKey references))data class SemanticFactEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "subject_entity_id")    val subjectEntityId: Long? = null,    @ColumnInfo(name = "predicate")    val predicate: String,    @ColumnInfo(name = "object_value")    val objectValue: String,    @ColumnInfo(name = "object_entity_id")    val objectEntityId: Long? = null,    @ColumnInfo(name = "confidence_alpha")    val confidenceAlpha: Float = 1.0f,    @ColumnInfo(name = "confidence_beta")    val confidenceBeta: Float = 1.0f,    @ColumnInfo(name = "source")    val source: String,  // user_explicit, user_implicit, inferred, llm_extracted    @ColumnInfo(name = "valid_from")    val validFrom: Long,    @ColumnInfo(name = "valid_to")    val validTo: Long? = null,    @ColumnInfo(name = "superseded_by")    val supersededBy: Long? = null,  // temporal versioning    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,) {    /** Bayesian confidence: alpha / (alpha + beta). */    val confidence: Float        get() = confidenceAlpha / (confidenceAlpha + confidenceBeta)}